import{z as l,x as B,o as t,c as p,q as r,j as s,D as E,d as A,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"AK、种类与熊彼特","description":"","frontmatter":{"title":"AK、种类与熊彼特","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ak-variety-schumpeter.md","filePath":"econ/ak-variety-schumpeter.md","lastUpdated":1791063341000}'),d={name:"econ/ak-variety-schumpeter.md"};function m(h,a,D,g,u,c){const o=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="ak、种类与熊彼特" tabindex="-1">AK、种类与熊彼特 <a class="header-anchor" href="#ak、种类与熊彼特" aria-label="Permalink to &quot;AK、种类与熊彼特&quot;">​</a></h1><div class="epigraph"><p>内生增长可以是资本报酬不递减、可以是品种扩张，也可以是旧产品被新产品摧毁；三句话不要写成同一个研发部门。</p><footer>—— Rebelo, JPE 1991 的 AK；Romer, JPE 1990 的种类；Aghion and Howitt, Econometrica 1992 的创造性破坏</footer></div><p><a href="/econ/endogenous-growth">上一课</a>已经用 Lucas 的人力资本与 Romer 的溢出/研发，把 \\(g\\) 从索洛参数里解放出来，并声明创新被写成平滑的 \\(\\dot{A}\\)、没有熊彼特式企业微观。本课的缺口是把三条<strong>不同的技术故事</strong>分分工：AK 刀刃、种类扩张、质量阶梯上的创造性破坏。错配下一课会说明加总 \\(A\\) 还可以来自配置；本课先把「技术如何内生」分成三套机制，不把人力资本积累再推一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内生增长课给出「知识非竞争 \\(\\Rightarrow\\) \\(g\\) 可被资源移动」。经验讨论却把 AK、品种数目与「创新摧毁旧租」混成一句「研发」。缺口是：报酬为何不递减到零，在三套模型里不是同一个答案。Rebelo 的 AK 让可积累要素的报酬恒定；Romer 1990 让中间品种类 \\(N\\) 扩张，最终产品看起来递增；Aghion–Howitt 让质量阶梯上的研发同时消灭在位者的垄断租。本课钉分工，不估计跨国回归。</p><p><span class="marginnote">AK 的 \\(Y=AK\\) 要求广义资本（含人力资本、知识）报酬恰好为 1。它是教学极限，不是观测到的资本份额等于 1。规模效应与刀刃仍在。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><span class="marginnote">术语翻译：水平创新是「多一种新货」——货架上多出一个新品种，旧的照卖（Romer 的种类）；垂直创新是「同一货更好」——新产品直接把旧的顶下货架（熊彼特的质量阶梯）。区分二者是分清专利与反垄断政策的第一步。</span></p><p>AK：\\(\\dot{K}=sAK-\\delta K\\)，人均增长 \\(sA-\\delta-n\\) 一类，政策改 \\(s\\) 即改稳态增长率。没有过渡到外生 \\(g\\) 的回归。种类：研发生产新蓝图，中间品种类增加提高最终产出；增长靠研发劳动力份额，在位品种继续存在——水平创新。熊彼特：研发瞄准更高质量，成功则取代旧品种，租从旧垄断转到新垄断——垂直创新，均衡里含有意的破坏。</p>',9)),(t(),s(i,null,{default:E(()=>[n(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENDO%5B%22%E5%86%85%E7%94%9F%20g%20%E7%9A%84%E5%85%B1%E5%90%8C%E9%97%AE%E9%A2%98%22%5D%20--%3E%20AK%5B%22AK%EF%BC%9A%E6%8A%A5%E9%85%AC%E4%B8%8D%E9%80%92%E5%87%8F%22%5D%0A%20%20ENDO%20--%3E%20VAR%5B%22%E7%A7%8D%E7%B1%BB%EF%BC%9A%E6%B0%B4%E5%B9%B3%E6%89%A9%E5%BC%A0%22%5D%0A%20%20ENDO%20--%3E%20SCH%5B%22%E7%86%8A%E5%BD%BC%E7%89%B9%EF%BC%9A%E8%B4%A8%E9%87%8F%E9%98%B6%E6%A2%AF%22%5D%0A%20%20AK%20--%3E%20G%5B%22%E5%A2%9E%E9%95%BF%E7%8E%87%E7%94%B1%E8%B5%84%E6%BA%90%E9%85%8D%E7%BD%AE%E5%86%B3%E5%AE%9A%22%5D%0A%20%20VAR%20--%3E%20G%0A%20%20SCH%20--%3E%20G%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"社会最优：AK 往往没有研发外部性（若 \\(A\\) 是私人资本）；种类模型有知识溢出与垄断扭曲；熊彼特还有商业窃取——私人研发可能过多或过少，符号不定。上一课「分散研发通常不足」主要对应溢出；本课不允许把那句话抄到创造性破坏上当定理。",-1)),a[4]||(a[4]=e("h3",{id:"三种故事不要共用同一政策按钮",tabindex:"-1"},[A("三种故事不要共用同一政策按钮 "),e("a",{class:"header-anchor",href:"#三种故事不要共用同一政策按钮","aria-label":'Permalink to "三种故事不要共用同一政策按钮"'},"​")],-1)),a[5]||(a[5]=e("p",null,"专利长度在种类模型里权衡静态扭曲与发明激励；在质量阶梯上还改变取代速度。教育补贴更贴近 Lucas，不是 Aghion–Howitt 的工业组织。把「提高 \\(s\\)」当 AK 政策，在种类/熊彼特里只改水平或改研发的机会成本，不保证同一 \\(g\\) 公式。",-1)),a[6]||(a[6]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=e("p",null,"报酬不递减：要么把知识写进广义 \\(K\\) 且弹性刚好为 1，要么用种类使加总像递增，要么用质量使「有效 \\(A\\)」沿阶梯跳。熊彼特的微观是：在位者知道自己会被取代，研发既创造又毁灭现值；均衡增长率依赖研发生产力与市场结构，不是外生 \\(g\\)。创造性破坏使企业微观出现又消失——上一课故意平滑掉的那一块。",-1)),(t(),s(i,null,{default:E(()=>[n(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENTR%5B%22%E7%A0%94%E5%8F%91%E8%80%85%E7%9E%84%E5%87%86%E6%9B%B4%E9%AB%98%E8%B4%A8%E9%87%8F%22%5D%20--%3E%20WIN%5B%22%E5%88%9B%E6%96%B0%E6%88%90%E5%8A%9F%3A%20%E5%9E%84%E6%96%AD%E7%A7%9F%E6%98%93%E4%B8%BB%22%5D%0A%20%20WIN%20--%3E%20KILL%5B%22%E6%97%A7%E5%93%81%E7%A7%8D%E8%A2%AB%E8%B8%A2%E5%87%BA%E5%B8%82%E5%9C%BA%22%5D%0A%20%20KILL%20--%3E%20OLD%5B%22%E6%97%A7%E5%9C%A8%E4%BD%8D%E8%80%85%E7%9A%84%E7%A7%9F%E4%B8%8E%E7%8E%B0%E5%80%BC%E5%BD%92%E9%9B%B6%22%5D%0A%20%20WIN%20--%3E%20TGT%5B%22%E6%96%B0%E5%9C%A8%E4%BD%8D%E8%80%85%E6%88%90%E4%B8%BA%E4%B8%8B%E4%B8%80%E4%B8%AA%E9%9D%B6%E5%AD%90%22%5D%0A%20%20TGT%20--%3E%7C%22%E9%A2%84%E6%9C%9F%E7%BB%88%E8%A2%AB%E5%8F%96%E4%BB%A3%2C%20%E7%BB%A7%E7%BB%AD%E6%8A%95%E5%85%A5%E7%A0%94%E5%8F%91%22%7C%20ENTR%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p><span class="marginnote">常见误区：初学者容易以为「研发永远多多益善」。熊彼特模型里有一笔商业窃取效应：你的创新把在位者的垄断租夺走，这部分收益是社会内部转移，不是新增产出——私人回报高于社会回报，均衡研发可能反而过多，符号并不确定。</span></p><p>半内生修正（\\(\\phi\\lt 1\\)）对三种故事都可能需要，否则规模效应过强。本课保留分工，不选「唯一正确」的内生增长。</p><p>Lucas 人力资本仍是第四条常见主干：积累对象是 \\(h\\) 而不是中间品种类或质量阶梯。上一课已经写过，本课不重推 \\(\\dot{h}\\)。经验讨论里「东亚靠教育」更贴近 Lucas，「新产业替代旧产业」更贴近熊彼特，「品种变多」更贴近 Romer 1990。把三者都叫「内生增长政策」会把教育补贴、专利与反垄断焊成同一个按钮。</p><p>AK 对索洛的翻转最干净：\\(s\\) 改增长率。种类与熊彼特里，\\(s\\) 改的是资本密度或研发的机会成本，稳态 \\(g\\) 由研发部门参数决定。不要用 AK 的比较静态去读另外两套模型的税率实验。</p><p><span class="marginnote">数字实例：AK 里 \\(g=sA-\\delta-n\\)。取 \\(A=0.3\\)、折旧加人口合计 5%：储蓄率 \\(s=20\\%\\) 时 \\(g=6\\%-5\\%=1\\%\\)；把 \\(s\\) 提到 \\(25\\%\\)，\\(g=7.5\\%-5\\%=2.5\\%\\)——储蓄率动 5 个点，增长率翻倍还多，这就是「刀刃」的含义，也是它招人怀疑的原因。</span></p><p><span class="marginnote">Romer 1990 的品种仍在市场上并存；Aghion–Howitt 的旧品种被踢出。经验上两者都有：新产品线与替代性创新。加总 TFP 看不出你用的是哪一套。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把熊彼特写成股市上的创造性破坏指数，也不把 AK 当发展中国家的储蓄政策。短期失业、货币仍不在增长主干。错配可以使加总 \\(A\\) 在技术不变时变动——下一课；本课的 \\(A\\) 仍是「生产函数里的技术故事」，不是残差的全部。CIP 与资产定价不在此检验这三种模型。</p><p>索洛残差看不出你用的是哪一套故事：品种增加、质量跳升与广义资本积累都可以表现为 \\(\\Delta\\ln A\\)。政策实验必须先声明机制。黄金律在三种模型里都要重写计划者问题，本课不把修正黄金律抄过来当 AK 的 \\(s\\)。</p><p>规模效应：种类与熊彼特的早期版本里人口越大 \\(g\\) 越高；经验上跨国 \\(g\\) 并不随人口线性上升，半内生把知识弹性降到 1 以下。AK 没有这条人口通道，刀刃改在资本报酬。三种故事的「政策改 \\(g\\)」含义因此不同，不能共用同一张政策表。</p><p>后课默认：谈到内生技术，能区分 AK、种类与质量阶梯，不把三者写成同一个 \\(\\dot{A}=\\eta L_A A\\)。下一课问：资源错配如何表现为同一个残差。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内生增长课给出 \\(g\\) 可被动；本课把机制分成 AK、种类、熊彼特。</li><li>AK 是报酬恒定的刀刃；种类是水平扩张；熊彼特是取代式垂直创新。</li><li>研发不足不是定理：创造性破坏下私人激励可过高。</li><li>加总 \\(A\\) 看不出故事；错配是残差的另一来源。</li><li>Lucas 人力资本仍是上一课的主干，本课不重推。</li><li>出处：Rebelo, JPE 1991；Romer, JPE 1990；Aghion and Howitt, Econometrica 1992。</li></ul>',13))])}const C=l(d,[["render",m]]);export{f as __pageData,C as default};
